+class ContactFormValidator {
+    constructor() {
+        this.form = document.getElementById('contactForm');
+        this.fields = {
+            fullName: {
+                input: document.getElementById('fullName'),
+                errorElement: document.getElementById('fullNameError'),
+                required: true,
+                validate: this.validateFullName.bind(this)
+            },
+            email: {
+                input: document.getElementById('email'),
+                errorElement: document.getElementById('emailError'),
+                required: true,
+                validate: this.validateEmail.bind(this)
+            },
+            phone: {
+                input: document.getElementById('phone'),
+                errorElement: document.getElementById('phoneError'),
+                required: false,
+                validate: this.validatePhone.bind(this)
+            }
+        };
+
+        this.init();
+    }
+
+    init() {
+        Object.values(this.fields).forEach(field => {
+            field.input.addEventListener('blur', () => this.validateField(field));
+            field.input.addEventListener('input', () => this.clearError(field));
+        });
+
+        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+    }
+
+    validateFullName(value) {
+        if (!value.trim()) {
+            return 'Full name is required';
+        }
+        if (value.trim().length < 2) {
+            return 'Full name must be at least 2 characters';
+        }
+        if (!/^[a-zA-Z\s'-]{2,}$/.test(value)) {
+            return 'Full name can only contain letters, spaces, hyphens, and apostrophes';
+        }
+        return null;
+    }
+
+    validateEmail(value) {
+        if (!value.trim()) {
+            return 'Email address is required';
+        }
+        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        if (!emailRegex.test(value)) {
+            return 'Please enter a valid email address';
+        }
+        return null;
+    }
+
+    validatePhone(value) {
+        if (!value.trim()) {
+            return null;
+        }
+        const phoneRegex = /^(\+?1[-.\s]?)?\(?[0-9]{3}\)?[-.\s]?[0-9]{3}[-.\s]?[0-9]{4}$/;
+        if (!phoneRegex.test(value)) {
+            return 'Please enter a valid phone number';
+        }
+        return null;
+    }
+
+    validateField(field) {
+        const error = field.validate(field.input.value);
+
+        if (error) {
+            this.showError(field, error);
+        } else {
+            this.clearError(field);
+            field.input.classList.add('is-valid');
+        }
+    }
+
+    showError(field, message) {
+        field.errorElement.textContent = message;
+        field.errorElement.classList.add('show');
+        field.input.classList.remove('is-valid');
+        field.input.classList.add('is-invalid');
+    }
+
+    clearError(field) {
+        field.errorElement.textContent = '';
+        field.errorElement.classList.remove('show');
+        field.input.classList.remove('is-invalid');
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+
+        let isValid = true;
+        Object.values(this.fields).forEach(field => {
+            this.validateField(field);
+            const error = field.validate(field.input.value);
+            if (error) {
+                isValid = false;
+            }
+        });
+
+        if (isValid) {
+            this.submitForm();
+        }
+    }
+
+    submitForm() {
+        const formData = {
+            fullName: this.fields.fullName.input.value,
+            email: this.fields.email.input.value,
+            phone: this.fields.phone.input.value
+        };
+
+        console.log('Form submitted:', formData);
+        alert('Thank you for contacting us! We will get back to you soon.\n\nName: ' + formData.fullName + '\nEmail: ' + formData.email + (formData.phone ? '\nPhone: ' + formData.phone : ''));
+        this.form.reset();
+        Object.values(this.fields).forEach(field => {
+            field.input.classList.remove('is-valid', 'is-invalid');
+            field.errorElement.classList.remove('show');
+            field.errorElement.textContent = '';
+        });
+    }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+    new ContactFormValidator();
+});
+
")

